'use strict';
const icons={lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/><path d="M12 14v3"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',book:'<path d="M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1v15"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-7l1-7Z"/>',clipboard:'<rect x="5" y="4" width="14" height="17" rx="2"/><rect x="9" y="2" width="6" height="4" rx="1"/><path d="m9 13 2 2 4-5"/>',gauge:'<circle cx="12" cy="12" r="9"/><path d="m12 12 4-4M5 12h1m6-7v1m6 6h1M8 17h8"/>',check:'<path d="m5 12 4 4L19 6"/>',users:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m1-18a3 3 0 0 1 0 6m2 5a5 5 0 0 1 3 5v2"/>',refresh:'<path d="M20 7a9 9 0 0 0-15-2L2 8m0-5v5h5m-3 9a9 9 0 0 0 15 2l3-3m0 5v-5h-5"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',arrowLeft:'<path d="M20 12H4m6-6-6 6 6 6"/>',arrowDown:'<path d="M12 3v18m-7-7 7 7 7-7"/>',arrowUp:'<path d="M12 21V3m-7 7 7-7 7 7"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',tag:'<path d="M3 3h8l10 10-8 8L3 11V3Z"/><circle cx="7.5" cy="7.5" r="1"/>',play:'<path d="m8 4 12 8-12 8V4Z"/>',settings:'<circle cx="12" cy="12" r="4"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>',thermometer:'<path d="M9 14V5a3 3 0 0 1 6 0v9a5 5 0 1 1-6 0Z"/><path d="M12 7v10"/>',drop:'<path d="M12 2S4 11 4 16a8 8 0 0 0 16 0c0-5-8-14-8-14Z"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',warning:'<path d="m12 3 10 18H2L12 3Z"/><path d="M12 9v5m0 3v1"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',chart:'<path d="M4 3v18h17M8 17v-5m5 5V8m5 9V4"/>',printer:'<path d="M7 8V3h10v5M7 17H3V8h18v9h-4M7 14h10v7H7V14Z"/>',chevron:'<path d="m9 5 7 7-7 7"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-2a8 8 0 0 1 16 0v2"/>',flag:'<path d="M5 22V3c5-4 9 4 15 0v11c-6 4-10-4-15 0"/>'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.info}</svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STORAGE='lototo-praktijk-v1';
const fresh=()=>({role:'operator',done:[],cases:{},visited:[],order:false,last:null,reading:{},fieldRead:false});
let saved=fresh(),storageOK=true;
try{const p=JSON.parse(localStorage.getItem(STORAGE));if(p&&typeof p==='object'){saved={...fresh(),...p};saved.role=['operator','monteur'].includes(p.role)?p.role:'operator';saved.done=Array.isArray(p.done)?[...new Set(p.done.filter(n=>Number.isInteger(n)&&n>=0&&n<8))]:[];saved.visited=Array.isArray(p.visited)?p.visited.filter(n=>Number.isInteger(n)&&n>=0&&n<4):[];saved.cases=p.cases&&typeof p.cases==='object'?p.cases:{};if(!p.last||!Array.isArray(p.last.answers)||p.last.answers.length!==exam.length)saved.last=null;}}catch{storageOK=false;}
let state={page:'home',index:0,menu:false,tab:'plant',energy:0,labSelection:null,lessonAnswers:{},caseStep:0,caseAnswers:[],caseChosen:null,caseDone:false,order:[3,0,5,1,4,2,7,6],orderChecked:false,examStarted:false,examIndex:0,examAnswers:Array(exam.length).fill(null),examSubmitted:false,toast:''};
function examPassed(){return !!saved.last&&saved.last.answers.filter((a,i)=>a===exam[i].correct).length>=13&&exam.every((q,i)=>!q.critical||saved.last.answers[i]===q.correct);}
function caseOrder(){return cases.map((_,i)=>i).sort((a,b)=>Number(cases[b].role===saved.role)-Number(cases[a].role===saved.role));}
function nextCase(){return caseOrder().find(i=>!saved.cases[i])??-1;}
function courseInfo(){return [
{short:'Basis leren',title:'Leer de basis van LOTOTO',instruction:'Lees 8 korte modules. Elke module sluit af met één oefenvraag.',time:'55–60 min',status:`${saved.done.length} van 8 modules afgerond`,done:saved.done.length===8},
{short:'Installatie onderzoeken',title:'Onderzoek de oefeninstallatie',instruction:'Ontdek 4 energiebronnen in het pompschema en zet de werkfasen op volgorde.',time:'8–10 min',status:`${Number(saved.visited.length===4)+Number(!!saved.order)} van 2 opdrachten afgerond`,done:saved.visited.length===4&&!!saved.order},
{short:'Scenario’s oefenen',title:'Maak keuzes in de praktijk',instruction:'Oefen met pomp, transporteur, pneumatische klep en ploegwissel.',time:'20–25 min',status:`${cases.filter((_,i)=>saved.cases[i]).length} van 4 scenario’s geoefend`,done:cases.every((_,i)=>saved.cases[i])},
{short:'Kennis toetsen',title:'Toets je kennis',instruction:'Beantwoord 16 vragen. De oefennorm is 13 goed én alle 4 kritieke vragen goed.',time:'15 min',status:examPassed()?'Oefennorm behaald':saved.last?'Herhalen na feedback':'Nog niet afgerond',done:examPassed()},
{short:'Naar de werkplek',title:'Bereid je praktijkgesprek voor',instruction:'Lees de werkplekkaart en neem de bespreekvragen mee naar je begeleider.',time:'5 min',status:saved.fieldRead?'Werkplekkaart gelezen':'Werkplekkaart nog lezen',done:!!saved.fieldRead}
];}
function nextStage(){return courseInfo().findIndex(s=>!s.done);}
function courseUnits(){return saved.done.length+Number(saved.visited.length===4)+Number(!!saved.order)+cases.filter((_,i)=>saved.cases[i]).length+Number(examPassed())+Number(!!saved.fieldRead);}
function courseProgress(){return Math.round(courseUnits()/16*100);}
function currentStage(){return ({module:0,lab:1,cases:2,scenario:2,exam:3,field:4})[state.page]??-1;}
function openStage(i){if(i===0)go('module',Math.max(0,nextModule()));if(i===1){state.tab=saved.visited.length===4&&!saved.order?'order':'plant';go('lab');}if(i===2)go('cases');if(i===3)go('exam');if(i===4)go('field');}
function stageRail(){return `<nav class="stage-rail no-print" aria-label="Positie in de leerroute">${courseInfo().map((s,i)=>`<button data-stage="${i}" aria-label="Leerstap ${i+1}: ${s.short}" class="${currentStage()===i?'active':''} ${s.done?'complete':''}" ${currentStage()===i?'aria-current="step"':''}><span>${s.done?icon('check'):i+1}</span><b>${s.short}</b></button>`).join('')}</nav>`;}
function lessonPart(){const p=saved.reading?.[state.index];return Number.isInteger(p)&&p>=0&&p<=4?p:0;}
function lessonGraphic(module,part){if(part!==1)return '';const rows=[
[['lock','LOCK OUT','Scheiden en vergrendelen'],['tag','TAG OUT','Markeren'],['check','TRY OUT','Controleren']],
[['bolt','VOEDING','Wat komt er binnen?'],['gauge','RESTENERGIE','Wat blijft achter?'],['refresh','TERUGVOEDING','Wat kan terugkomen?']],
[['clipboard','WERKOPDRACHT','Taak en nummer'],['settings','INSTALLATIE','Werkgrens ter plaatse'],['users','AFSTEMMING','Iedereen geïnformeerd']],
[['settings','SCHEIDEN','Juiste scheidingspunt'],['lock','BORGEN','Voorkom bediening'],['tag','MARKEREN','Wie en waarom']],
[['gauge','DRUK','Veilig afvoeren'],['settings','BEWEGING','Veilig blokkeren'],['thermometer','WARMTE','Veilig afkoelen']],
[['bolt','ELEKTRISCH','Bevoegd verifiëren'],['gauge','PROCES','Druk en product'],['settings','MECHANISCH','Stilstand en borging']],
[['lock','ISOLATIESLOTEN','Energie gescheiden'],['clipboard','GROEPSSLOTKAST','Sleutels geborgd'],['users','PERSOONLIJK','Iedereen beschermd']],
[['settings','CONTROLE','Werk gereed'],['users','OVERDRACHT','Mensen veilig'],['refresh','HERSTART','Gecontroleerd starten']]
];return `<div class="concept-flow" aria-label="Samenvatting van de belangrijkste begrippen">${rows[module].map(x=>`<div>${icon(x[0])}<b>${x[1]}</b><span>${x[2]}</span></div>`).join('')}</div>`;}

function persist(){try{localStorage.setItem(STORAGE,JSON.stringify(saved));}catch{storageOK=false;}}
const progress=()=>Math.round(new Set(saved.done).size/8*100);
const nextModule=()=>modules.findIndex((_,i)=>!saved.done.includes(i));
const labels={welcome:'Startpagina',home:'Start & voortgang',module:'Leermodule',energy:'Energiebronnen',lab:'Oefeninstallatie',cases:'Praktijkscenario’s',scenario:'Praktijkscenario',exam:'Kennistoets',field:'Werkplekkaart',sources:'Begrippen & bronnen'};
function route(){const parts=location.hash.slice(1).split('/');if(Object.hasOwn(labels,parts[0])){state.page=parts[0];state.index=Math.max(0,Math.min(parts[0]==='module'?7:3,parseInt(parts[1],10)||0));}else state.page='welcome';}
function go(page,index=0){if(page==='module'&&saved.done.includes(index)){saved.reading=saved.reading&&typeof saved.reading==='object'?saved.reading:{};saved.reading[index]=0;persist();}state.page=page;state.index=index;state.menu=false;history.pushState(null,'',`#${page}${['module','scenario'].includes(page)?'/'+index:''}`);render();window.scrollTo({top:0,behavior:'instant'});document.querySelector('h1')?.focus({preventScroll:true});}
function announce(text){document.getElementById('live').textContent=text;}
function toast(text){state.toast=text;render();setTimeout(()=>{state.toast='';document.querySelector('.toast')?.remove();},3500);}
function header(eyebrow,title,desc='',extra=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1 tabindex="-1">${title}</h1>${desc?`<p>${desc}</p>`:''}</div>${extra}</div>`;}
function navItem(page,label,ico,count=''){const active=state.page===page||(page==='home'&&state.page==='module')||(page==='cases'&&state.page==='scenario');return `<button data-go="${page}" class="${active?'active':''}" ${active?'aria-current="page"':''}>${icon(ico)}${label}${count?`<span class="count">${count}</span>`:''}</button>`;}
function render(){document.title=state.page==='welcome'?'LOTOTO — Zeker weten. Veilig werken.':'LOTOTO — '+labels[state.page];if(state.page==='welcome'){document.getElementById('app').innerHTML=welcomeView();return;}const pages={home:homeView,module:moduleView,energy:energyView,lab:labView,cases:casesView,scenario:scenarioView,exam:examView,field:fieldView,sources:sourcesView};const course=courseInfo();document.getElementById('app').innerHTML=`<div class="shell">${state.menu?'<div class="nav-backdrop" data-action="menu"></div>':''}<aside class="sidebar ${state.menu?'open':''}" aria-label="Hoofdnavigatie"><a href="#home" class="brand" data-go="home"><span class="brandmark">${icon('lock')}</span><span><strong>LOTOTO</strong><small>Praktijkacademie</small></span></a><nav class="nav">${navItem('home','Start & voortgang','grid')}</nav><div class="side-divider"></div><div class="navlabel">JOUW 5 LEERSTAPPEN</div><nav class="nav learning-nav">${course.map((s,i)=>`<button data-stage="${i}" aria-label="Leerstap ${i+1}: ${s.short}" class="${currentStage()===i?'active':''}" ${currentStage()===i?'aria-current="step"':''}><span class="nav-step">${s.done?icon('check'):i+1}</span><span>${s.short}</span></button>`).join('')}</nav><div class="side-divider"></div><div class="navlabel">NASLAG · OP ELK MOMENT</div><nav class="nav">${navItem('energy','Energiebronnen','bolt')}${navItem('sources','Begrippen & bronnen','book')}</nav><div class="side-bottom"><div class="side-progress"><div class="row"><span>Hele leerroute</span><strong>${courseProgress()}%</strong></div><div class="progress" role="progressbar" aria-valuenow="${courseProgress()}" aria-valuemin="0" aria-valuemax="100" aria-label="Voortgang hele leerroute"><i style="width:${courseProgress()}%"></i></div><small>${courseUnits()} van 16 leeractiviteiten afgerond</small></div><div class="safety-mini">${icon('shield')}<span>Oefenomgeving<br>Geen werkvrijgave</span></div></div></aside><div class="workspace"><header class="topbar"><div class="flex"><button class="mobile-toggle" data-action="menu" aria-label="Menu openen of sluiten" aria-expanded="${state.menu}">${icon('menu')}</button><div class="breadcrumbs"><span>LOTOTO</span>${icon('chevron')}<strong>${labels[state.page]}</strong></div></div><div class="topright"><label class="role-wrap"><span>Mijn rol</span><select id="role" aria-label="Jouw rol"><option value="operator" ${saved.role==='operator'?'selected':''}>Operator</option><option value="monteur" ${saved.role==='monteur'?'selected':''}>Monteur TD</option></select></label></div></header><main id="main" class="main"><button class="back-website" data-go="welcome">${icon('arrowLeft')} Naar de startpagina</button>${currentStage()>=0?stageRail():''}${pages[state.page]()}<footer class="footer"><span>LOTOTO Praktijkacademie · Oefenen voor de procesindustrie</span><span>${storageOK?'Voortgang bewaard op dit apparaat':'Voortgang wordt niet bewaard'} · <button data-action="reset">Voortgang wissen</button></span></footer></main></div></div>${state.toast?`<div class="toast" role="status">${esc(state.toast)}</div>`:''}<dialog class="dialog" id="reset-dialog" aria-labelledby="reset-title"><h2 id="reset-title">Opnieuw beginnen?</h2><p>Je afgeronde modules, scenario’s en toetsresultaat worden op dit apparaat gewist.</p><div class="flex"><button class="btn secondary" data-action="cancel-reset">Annuleren</button><button class="btn" data-action="confirm-reset">Voortgang wissen</button></div></dialog>`;}
function plantSVG(interactive=true){const point=(x,y,n,label)=>`<g class="hotspot" ${interactive?`role="button" tabindex="0" data-point="${n}" aria-label="Bekijk energiebron ${n+1}: ${label}"`:''}><circle cx="${x}" cy="${y}" r="16"/><text x="${x}" y="${y+5}" text-anchor="middle" font-size="13" fill="#163337">${saved.visited.includes(n)&&state.page==='lab'?'✓':n+1}</text></g>`;return `<svg class="plant-svg" viewBox="0 0 550 285" role="group" aria-label="Vereenvoudigd procesdiagram van tank T-201, pomp P-204, motor M en warmtebron. Vier aanklikbare energiebronnen."><defs><pattern id="hatch" width="8" height="8" patternUnits="userSpaceOnUse"><path d="M-2 2 2-2M0 8 8 0M6 10l4-4" stroke="#557975" stroke-width="1"/></pattern></defs><path class="pipe" d="M76 177h145m55 0h143V98h77"/><rect class="equipment" x="30" y="70" width="85" height="107" rx="3"/><path d="M32 128h81v47H32Z" fill="#476e6e"/><path d="M32 127c14-6 28 6 41 0s25 6 40 0" stroke="#9abbb5" fill="none"/><text x="72" y="55" text-anchor="middle" fill="#d1e1d9" font-size="12">T-201</text><text x="72" y="151" text-anchor="middle" fill="#d1e1d9" font-size="11">PRODUCT</text><path class="equipment" d="m140 166 24 22v-22l-24 22Z"/><path d="M152 166v-17m-9 0h18" stroke="#9abbb5" stroke-width="2"/><text x="151" y="213" fill="#a3bdb7" font-size="11" text-anchor="middle">XV-21</text><path class="equipment" d="m351 166 24 22v-22l-24 22Z"/><path d="M363 166v-17m-9 0h18" stroke="#9abbb5" stroke-width="2"/><text x="363" y="213" fill="#a3bdb7" font-size="11" text-anchor="middle">XV-22</text><circle class="equipment" cx="247" cy="177" r="28"/><path d="m230 158 37 19-37 19Z" stroke="#b2cdc1" fill="#30565b" stroke-width="2"/><path d="M247 205v17m-28 0h56" stroke="#9abbb5" stroke-width="3"/><text x="247" y="244" text-anchor="middle" fill="#d1e1d9" font-size="12">P-204</text><path d="M269 190l34 39" stroke="#a4bcb6" stroke-width="6"/><circle class="equipment" cx="316" cy="242" r="21"/><text x="316" y="248" text-anchor="middle" font-size="17" fill="#d1e1d9">M</text><path class="wire" d="M475 58h-158v163"/><rect x="437" y="42" width="63" height="33" rx="3" fill="#27464b" stroke="#b8ca87"/><path d="m456 50 10 15m-10 0 10-15" stroke="#d8ef80" stroke-width="2"/><text x="469" y="31" fill="#c4d3b1" text-anchor="middle" font-size="11">400 V</text><path d="M306 177v-34" stroke="#9bbdb4" stroke-width="2"/><circle class="equipment" cx="306" cy="132" r="13"/><path d="m306 132 6-6" stroke="#d8ef80" stroke-width="2"/><text x="298" y="107" fill="#aac3bd" font-size="10">PI</text><path d="M166 264v-31h49" stroke="#f3a26f" stroke-width="3" stroke-dasharray="5 4" fill="none"/><text x="76" y="267" fill="#d6b8a3" font-size="10">WARMTE</text><text x="487" y="122" fill="#a9c0b9" text-anchor="middle" font-size="10">PERSLEIDING</text>${point(358,58,0,'elektrische voeding')}${point(430,98,1,'procesdruk en product')}${point(279,212,2,'as en beweging')}${point(165,235,3,'warmte en temperatuur')}</svg>`;}
function homeView(){const stage=nextStage(),info=courseInfo(),next=nextModule(),started=courseUnits()>0||Object.keys(saved.reading||{}).length>0;const title=stage===0?`Module ${next+1}: ${modules[next].short}`:info[stage]?.title;const tasks=['Lees de uitleg en beantwoord de oefenvraag. Na elk onderdeel klik je op de groene knop om verder te gaan.','Onderzoek de vier energiebronnen van pomp P-204. Zet daarna de acht fasen van veiligstellen in de juiste volgorde.','Oefen alle vier de scenario’s. Kies bij elke beslissing één antwoord en lees de uitleg voordat je verdergaat.','Beantwoord de 16 vragen. Bekijk je resultaat en herhaal de onderwerpen die je nog lastig vindt.','Lees de werkplekkaart en de bespreekvragen. Neem de kaart mee naar je praktijkbegeleider.'];return `${header('LOTOTO · VOOR OPERATORS EN MONTEURS',stage<0?'Je leerroute is afgerond.':started?'Ga verder waar je was.':'Welkom. Hier start je.','Je leert hoe je gevaarlijke energie herkent en hoe veiligstellen werkt.',`<span class="pill outline">${icon('clock')} 90–110 min · in delen te volgen</span>`)}<section class="start-briefing"><div class="start-body"><div class="eyebrow">${stage<0?'VOLGENDE STAP: JE WERKPLEK':started?'JOUW VOLGENDE OPDRACHT':'START HIER · LEERSTAP 1 VAN 5'}</div><h2>${stage<0?'Bespreek de praktijk met je begeleider.':title}</h2><p>${stage<0?'Je hebt de leeractiviteiten afgerond. Op jouw locatie zijn aanvullende instructie, praktijkbeoordeling en de juiste bevoegdheid nodig.':tasks[stage]}</p><button class="btn primary main-cta" data-action="continue-course">${icon(stage<0?'book':'play')}${stage<0?'Open de werkplekkaart':stage===0?(started?`Verder met module ${next+1}`:'Start module 1 · de basis'):stage===1?'Verder met de oefeninstallatie':stage===2?'Verder met de scenario’s':stage===3?'Naar de kennistoets':'Lees de werkplekkaart'}${icon('arrow')}</button><div class="start-hint">${stage===0?'Eerst 4 korte uitlegkaarten, daarna 1 oefenvraag.':stage<0?'Je kunt alle onderdelen hieronder opnieuw bekijken.':'Je voortgang wordt automatisch op dit apparaat bewaard.'}</div></div><aside class="briefing-dossier"><div class="dossier-heading">${icon('clipboard')} JOUW PRAKTIJKCONTEXT <span class="equipment-tag">P-204</span></div><h3>Onderhoud aan een productpomp</h3><p>Een monteur vervangt de afdichting. Welke energie moet het team eerst beheersen?</p><div class="mini-process" aria-label="Processtroom: opslagtank, productpomp, persleiding"><span><b>T-201</b>Opslagtank</span>${icon('arrow')}<span class="process-pump"><b>P-204</b>Productpomp</span>${icon('arrow')}<span><b>UIT</b>Persleiding</span></div><div class="dossier-caption">${icon('info')} Fictieve oefencasus · geen echte bediening</div></aside></section><div class="route-intro"><h2>Dit ga je doen</h2><p>Volg de vijf leerstappen. Je kunt tussendoor stoppen en later verdergaan.</p></div><ol class="course-route">${info.map((s,i)=>`<li class="route-stop ${s.done?'is-done':''} ${i===stage?'is-current':''}"><span class="route-node">${s.done?icon('check'):String(i+1).padStart(2,'0')}</span><div class="route-description"><div class="route-title"><h3>${s.title}</h3><span class="pill ${s.done?'':'outline'}">${s.done?'Afgerond':i===stage?'Jouw volgende stap':'Daarna'}</span></div><p>${s.instruction}</p><span class="route-meta">${s.status} · ${s.time}</span></div><button class="route-open" data-stage="${i}" aria-label="${s.done?'Herhaal':'Open'} leerstap ${i+1}: ${s.title}">${s.done?'Herhalen':'Bekijken'} ${icon('chevron')}</button></li>`).join('')}</ol><div class="notice">${icon('info')}<p><strong>Hoe weet je dat je klaar bent?</strong> Rond 8 modules, 2 installatieoefeningen en 4 scenario’s af, haal de oefennorm van de kennistoets en lees de werkplekkaart. Naslag is beschikbaar via het menu.</p></div>`;}
function moduleView(){const m=modules[state.index],a=state.lessonAnswers[state.index],done=saved.done.includes(state.index),right=a===m.q.correct,part=lessonPart(),b=m.blocks[part];return `${header(`LEERSTAP 1 · MODULE ${state.index+1} VAN 8 · ${m.time} MIN`,m.title,m.goal)}<div class="lesson-workspace"><div><div class="lesson-position"><span>${part<4?`Uitlegkaart ${part+1} van 4`:'Oefenvraag · kies één antwoord'}</span><div class="lesson-dots" aria-label="${part<4?'Uitlegkaart '+(part+1):'Oefenvraag'}">${[0,1,2,3,4].map(i=>`<span class="${i<part?'done':i===part?'current':''}"></span>`).join('')}</div></div>${part<4?`<section class="instruction-card"><div class="card-label"><span class="equipment-tag">L${state.index+1} / ${String(part+1).padStart(2,'0')}</span><span>LEES DEZE UITLEG</span></div><h2 tabindex="-1" id="lesson-content-title">${b[0]}</h2>${part===0?`<p class="lesson-intro">${m.intro}</p>`:''}<p class="lesson-copy">${b[1]}</p>${lessonGraphic(state.index,part)}<div class="lesson-controls"><button class="btn secondary" data-lesson-part="${part-1}" ${part===0?'disabled':''}>${icon('arrowLeft')} Vorige uitleg</button><button class="btn primary" data-lesson-part="${part+1}">${part===3?'Naar de oefenvraag':`Verder · uitleg ${part+2} van 4`} ${icon('arrow')}</button></div></section>`:`<section class="quiz-box" style="margin-top:0" aria-label="Oefenvraag"><div class="eyebrow">PAS TOE WAT JE HEBT GELEERD</div><h2 class="question-title" tabindex="-1" id="lesson-content-title">${m.q.text}</h2><p class="small-text">Klik op antwoord A, B, C of D. Lees daarna de feedback.</p><div class="answers">${m.q.options.map((o,i)=>`<button class="answer ${a===i?(right?'right':'wrong'):''}" data-lesson-answer="${i}" ${right?'disabled':''}><span class="letter">${'ABCD'[i]}</span><span>${o}</span></button>`).join('')}</div>${a!==undefined?`<div class="feedback ${right?'':'bad'}" role="status"><strong>${right?'Goed gekozen. Klik hieronder om verder te gaan.':'Dit is nog niet veilig. Lees de uitleg en kies opnieuw.'}</strong>${m.q.why}</div>`:''}<div class="question-actions"><button class="btn secondary" data-lesson-part="0">${icon('book')} Uitleg teruglezen</button><button class="btn primary" data-action="complete-module" ${!right&&!done?'disabled':''}>${modules.findIndex((_,i)=>i!==state.index&&!saved.done.includes(i))<0?'Afronden · volgende leerstap':`Afronden · naar module ${modules.findIndex((_,i)=>i!==state.index&&!saved.done.includes(i))+1}`} ${icon('arrow')}</button></div>${!right&&!done?'<p class="small-text" style="margin:15px 0 0">De vervolgknop wordt actief zodra je het juiste antwoord kiest.</p>':''}</section>`}</div><aside class="lesson-companion"><div class="companion-heading">${icon(m.icon)} ONTHOUD</div><p>${m.take}</p><div class="role-note"><b>${saved.role==='operator'?'Als operator':'Als monteur TD'}</b><p>${saved.role==='operator'?'Breng proceskennis in en stem de stop en overdracht af. Voer alleen handelingen uit waarvoor je bevoegd bent.':'Controleer de werkgrens en je persoonlijke bescherming. Begin pas na verificatie en vrijgave.'}</p></div><details class="module-picker"><summary>Alle 8 modules bekijken</summary><ul class="lesson-nav">${modules.map((x,i)=>`<li><button data-go="module" data-index="${i}" class="${i===state.index?'current':''}"><span>${saved.done.includes(i)?'✓':i+1}</span>${x.short}</button></li>`).join('')}</ul></details></aside></div>`;}
function energyView(){const e=energies[state.energy];return `${header('HERKEN DE BRON','Energie heeft meer dan één vorm.','Selecteer een energiebron. Bekijk het gevaar, de beheersmaatregel en de controle.')}<div class="knowledge-grid">${energies.map((x,i)=>`<button class="energy-card ${i===state.energy?'selected':''}" data-energy="${i}" aria-pressed="${i===state.energy}"><span class="energy-icon" style="background:${x.color}45">${icon(x.icon)}</span><h3>${x.name}</h3><p>${x.example}</p></button>`).join('')}</div><section class="energy-detail" aria-live="polite"><div><div class="eyebrow">${e.name.toUpperCase()} · GEVAAR & BEHEERSING</div><h3>${e.risk}</h3><p>${e.control}</p></div><div><div class="eyebrow">${icon('check')} HOE WEET JE DAT HET VEILIG IS?</div><h3>Controleer het resultaat</h3><p>${e.verify}</p></div></section><div class="notice warning">${icon('warning')}<p><strong>Chemisch gevaar loopt vaak mee met het proces.</strong> Brandbaar, giftig, bijtend of zuurstofverdringend product moet ook worden beheerst. LOTOTO vervangt geen gasmeting, ventilatie, werkvergunning of andere aanvullende maatregel die jouw taak vereist.</p></div><button class="btn" data-go="lab">Herken energie in de installatie ${icon('arrow')}</button>`;}
const labSources=[{title:'Elektrische voeding',sub:'400 V · motor M',text:'De motor kan via de voeding opnieuw worden gestart. Ook een omvormer of extra voeding kan energie leveren. Identificeer en scheid alle voedingen volgens het plan; laat de elektrische verificatie bevoegd uitvoeren.'},{title:'Procesdruk en product',sub:'Tank, zuigzijde én perszijde',text:'De pomp kan vanuit beide zijden product en druk ontvangen. Gesloten afsluiters garanderen geen drukloze, lege werkplek. Het isolatieplan bepaalt de vereiste scheiding, veilige afvoer en verificatie.'},{title:'Mechanische beweging',sub:'Motoras · koppeling · pomp',text:'Draaiende delen kunnen nog nalopen of door een processtroom in beweging komen. De werkgrens moet ook dit voorkomen. Controleer stilstand en de voorgeschreven borging vóór je aan de koppeling werkt.'},{title:'Warmte en temperatuur',sub:'Warm product · warmtebron',text:'In dit dossier is de pomp verwarmd. Ook na uitschakelen blijven onderdelen en product heet. Neem de warmtebron mee in het plan en controleer de veilige temperatuur volgens de procedure.'}];
function labView(){const n=state.labSelection,first=labSources.findIndex((_,i)=>!saved.visited.includes(i));return `${header('LEERSTAP 2 VAN 5 · INSTALLATIE ONDERZOEKEN','Onderzoek pomp P-204.','Je doet hier twee opdrachten: energiebronnen onderzoeken en de werkvolgorde oefenen.')}<div class="tabs" aria-label="Installatieopdracht kiezen"><button class="tab ${state.tab==='plant'?'active':''}" data-tab="plant">${saved.visited.length===4?'✓':'A'} · Energiebronnen</button><button class="tab ${state.tab==='order'?'active':''}" data-tab="order">${saved.order?'✓':'B'} · Werkvolgorde</button></div>${state.tab==='plant'?`<div class="task-callout"><span class="task-code">OPDRACHT A</span><div><strong>${first<0?'Vier energiebronnen onderzocht.':'Klik op '+(first+1)+' in het schema.'}</strong><p>${first<0?'Ga verder met opdracht B: de werkvolgorde.':'Lees de uitleg die onder het schema verschijnt. Klik daarna op de groene knop voor de volgende bron. Je kunt ook de lijst naast het schema gebruiken.'}</p></div><span class="pill outline">${saved.visited.length} / 4 bekeken</span></div><div class="lab-grid"><div class="plant-panel"><div class="diagram-top"><span>PROCESDIAGRAM / P-204</span><span>OEFENCASUS</span></div>${plantSVG()}<p class="diagram-caption">Vereenvoudigd oefenschema · geen isolatieplan</p></div><div class="lab-list">${labSources.map((s,i)=>`<button class="lab-item ${n===i?'active':''}" data-point="${i}" aria-pressed="${n===i}"><span class="index">${saved.visited.includes(i)?'✓':i+1}</span><span><strong>${s.title}</strong><small>${s.sub} · ${saved.visited.includes(i)?'Bekeken':'Klik om te onderzoeken'}</small></span>${icon('chevron')}</button>`).join('')}</div></div>${n!==null?`<section class="energy-readout" aria-live="polite" id="source-explanation" tabindex="-1"><div class="readout-header"><span class="equipment-tag">P-204 / E${n+1}</span><span>ENERGIEBRON ${n+1} VAN 4</span></div><h2>${labSources[n].title}</h2><p>${labSources[n].text}</p><div class="question-actions"><span class="small-text">${first<0?'Opdracht A is afgerond.':'Gelezen? Onderzoek nu de volgende bron.'}</span>${first<0?'<button class="btn primary" data-tab="order">Verder naar opdracht B →</button>':`<button class="btn primary" data-point="${first}">Bekijk bron ${first+1} ${icon('arrow')}</button>`}</div></section>`:first<0?'<button class="btn primary" data-tab="order" style="margin-top:20px">Verder naar opdracht B →</button>':''}<div class="notice">${icon('info')}<p>De nummers wijzen gevaren aan in een oefenschema. Bij een echte installatie bepaalt het goedgekeurde isolatieplan waar, hoe en door wie wordt veiliggesteld.</p></div>`:`<div class="task-callout"><span class="task-code">OPDRACHT B</span><div><strong>Zet de acht fasen op volgorde.</strong><p>Verplaats een fase met de pijlen. Klik daarna op ‘Controleer mijn volgorde’. Bij een juiste volgorde ga je verder naar de scenario’s.</p></div></div>${orderView()}`}`;}
function orderView(){const ok=state.order.every((x,i)=>x===i);return `<div class="content-layout"><section><ol class="order-list">${state.order.map((x,i)=>`<li class="${state.orderChecked?(x===i?'correct-order':'wrong-order'):''}"><span class="order-num">${String(i+1).padStart(2,'0')}</span><strong>${steps[x][0]}</strong><span class="order-buttons"><button data-move="${i}" data-direction="-1" aria-label="${steps[x][0]} één plaats omhoog" ${i===0?'disabled':''}>${icon('arrowUp')}</button><button data-move="${i}" data-direction="1" aria-label="${steps[x][0]} één plaats omlaag" ${i===7?'disabled':''}>${icon('arrowDown')}</button></span></li>`).join('')}</ol><div class="flex"><button class="btn" data-action="check-order">Controleer mijn volgorde ${icon('check')}</button><button class="btn secondary" data-action="shuffle-order">Opnieuw oefenen</button></div>${state.orderChecked?`<div class="feedback ${ok?'':'bad'}" role="status"><strong>${ok?'De volgorde klopt.':'Nog niet helemaal. De gemarkeerde stappen staan niet op de juiste plek.'}</strong>${ok?'Je hebt de hoofdfasen op volgorde gezet. Pas dit nu toe in een praktijkscenario.':'Denk: eerst plannen en stoppen, dan scheiden en borgen. Beheers restenergie voordat je verifieert. Werkvrijgave volgt daarna; herstarten is de laatste fase.'}</div>${ok?'<button class="btn primary" style="margin-top:18px" data-action="after-order">Verder met de leerroute →</button>':''}`:''}</section><aside class="aside-card sticky"><span class="bigicon">${icon('clipboard')}</span><h3>Een leerroute, geen schakelplan</h3><p>Deze acht fasen helpen je het principe te begrijpen. De technische details en samenhang van handelingen staan in de procedure van jouw installatie.</p><p>Ondersteun bijvoorbeeld een last voordat druk wordt afgebouwd als de procedure dat voorschrijft.</p></aside></div>`;}
function casesView(){const next=nextCase(),count=cases.filter((_,i)=>saved.cases[i]).length;return `${header('LEERSTAP 3 VAN 5 · PRAKTIJKSCENARIO’S','Oefen je beslissingen.','Doorloop de vier scenario’s. Elk scenario bestaat uit vier keuzes met directe feedback.',`<span class="pill outline">${count} / 4 geoefend</span>`)}<section class="task-callout"><span class="task-code">JOUW OPDRACHT</span><div><strong>${next<0?'Alle vier de scenario’s geoefend.':`Ga verder met: ${cases[next].title}`}</strong><p>${next<0?'Je kunt nu je kennis toetsen.':'Klik op de groene knop. Kies telkens één antwoord, lees de feedback en klik op ‘Volgende beslissing’.'}</p></div>${next<0?'<button class="btn primary" data-go="exam">Verder naar de kennistoets →</button>':`<button class="btn primary" data-case="${next}">Start dit scenario ${icon('arrow')}</button>`}</section><div class="case-grid">${caseOrder().map(i=>{const c=cases[i];return `<article class="case-card"><div class="case-art">${icon(c.icon)}<span class="equipment-tag">${['P-204','CV-102','XV-310','WK-04'][i]}</span><span class="pill outline">${saved.cases[i]?'✓ GEOEFEND':'NOG TE DOEN'}</span></div><div class="case-body"><h3>${c.title}</h3><p>${c.sub}</p><div class="flex"><span class="small-text">5–7 min · 4 beslissingen</span><button class="btn secondary small" data-case="${i}">${saved.cases[i]?'Nogmaals oefenen':'Scenario bekijken'} ${icon('arrow')}</button></div></div></article>`;}).join('')}</div>`;}
function scenarioView(){const c=cases[state.index],q=c.questions[state.caseStep];if(state.caseDone){const correct=state.caseAnswers.filter((a,i)=>a===c.questions[i].c).length;return `${header('LEERSTAP 3 · SCENARIO AFGEROND',c.title)}<div class="result-summary"><div class="result-score">${correct}<span style="font-size:1.8rem"> / 4</span></div><div><h2>${correct===4?'Je koos vier keer veilig.':'Goed dat je dit hier oefent.'}</h2><p>${correct===4?'Je hebt de beslissingen in dit scenario goed beoordeeld.':'Bekijk de uitleg bij de beslissingen en oefen het scenario nog eens.'}</p></div></div>${c.questions.map((x,i)=>`<details class="review-row ${state.caseAnswers[i]===x.c?'':'incorrect'}" ${state.caseAnswers[i]!==x.c?'open':''}><summary>${icon(state.caseAnswers[i]===x.c?'check':'warning')}<span>${i+1}. ${x.q}</span></summary><div class="review-content"><p class="${state.caseAnswers[i]!==x.c?'answer-given':''}">Jouw keuze: ${x.a[state.caseAnswers[i]]}</p><p><strong>Veilige keuze:</strong> ${x.a[x.c]}</p><p>${x.why}</p></div></details>`).join('')}<div class="flex" style="margin-top:25px"><button class="btn primary" data-go="${nextCase()<0?'exam':'cases'}">${nextCase()<0?'Verder naar de kennistoets':'Verder naar het volgende scenario'} ${icon('arrow')}</button><button class="btn secondary" data-case="${state.index}">Dit scenario herhalen</button></div>`;}
const answered=state.caseChosen!==null,right=state.caseChosen===q.c;return `${header(`LEERSTAP 3 · SCENARIO ${state.index+1} · BESLISSING ${state.caseStep+1} VAN 4`,c.title)}<div class="content-layout"><div><div class="case-scenario"><div class="eyebrow">SITUATIE</div><p>${c.intro}</p></div><div class="mini-steps">${c.questions.map((_,i)=>`<span class="${i<state.caseStep?'done':i===state.caseStep?'current':''}"></span>`).join('')}</div><section class="quiz-box" style="margin-top:0"><div class="eyebrow">KLIK OP ÉÉN ANTWOORD EN LEES DE FEEDBACK</div><h3>${q.q}</h3><div class="answers">${q.a.map((a,i)=>`<button class="answer ${answered&&i===q.c?'right':answered&&i===state.caseChosen?'wrong':''}" data-case-answer="${i}" ${answered?'disabled':''}><span class="letter">${'ABC'[i]}</span><span>${a}</span></button>`).join('')}</div>${answered?`<div class="feedback ${right?'':'bad'}" role="status"><strong>${right?'Veilige keuze.':'Deze keuze is onveilig.'}</strong>${q.why}${!right?`<br><b>Veilige keuze:</b> ${q.a[q.c]}`:''}</div><div class="question-actions"><span class="small-text">We gaan verder vanuit de veilige keuze.</span><button class="btn" data-action="next-case">${state.caseStep===3?'Bekijk resultaat':'Volgende beslissing'} ${icon('arrow')}</button></div>`:''}</section></div><aside class="aside-card sticky"><div class="eyebrow">JOUW OPDRACHT</div><h3>Neem een veilig besluit</h3><p>Je hoeft geen afsluiters of schakelaars te bedienen. Je beoordeelt of de voorwaarden voor veilig werken kloppen.</p><p>Bij twijfel of een afwijking is stoppen en afstemmen een professionele keuze.</p><button class="btn secondary" data-go="cases">Terug naar scenario’s</button></aside></div>`;}
function examView(){if(state.examSubmitted)return examResult(state.examAnswers);if(!state.examStarted)return `${header('CHECK JE KENNIS','Ben je klaar voor de volgende stap?','Toets je begrip van veiligstellen. Bespreek de praktijktoepassing daarna met je begeleider.')}<div class="exam-start"><div class="exam-banner">${icon('clipboard')}<h2>De LOTOTO-kennistoets</h2><p>Je krijgt 16 meerkeuzevragen. Kies steeds één antwoord. Je kunt teruggaan en antwoorden wijzigen; de uitleg krijg je na het afronden.</p><div class="exam-stats"><div><strong>16</strong><span>praktijkgerichte vragen</span></div><div><strong>± 15 min</strong><span>zonder tijdsdruk</span></div><div><strong>13 / 16</strong><span>minimaal goed</span></div></div><p><b>Daarnaast moeten alle 4 kritieke veiligheidsvragen goed zijn.</b> Dit is een oefennorm van deze leeromgeving, geen erkend examen of bevoegdverklaring.</p><button class="btn primary" data-action="start-exam">Start de kennistoets ${icon('arrow')}</button></div>${saved.last?`<div class="paper" style="margin-top:20px"><div class="row"><div><h3>Je laatste resultaat</h3><p class="small-text" style="margin:7px 0 0">${new Date(saved.last.date).toLocaleDateString('nl-NL')} · ${saved.last.answers.filter((a,i)=>a===exam[i].correct).length} van 16 goed</p></div><button class="btn secondary" data-action="last-result">Bekijk uitleg</button></div></div>`:''}<div class="notice">${icon('info')}<p>Je toetsresultaat wordt op dit apparaat opgeslagen. Een lopende poging blijft bewaard zolang deze pagina open is. Er worden geen resultaten naar een werkgever of LMS verstuurd.</p></div></div>`;
const i=state.examIndex,q=exam[i],a=state.examAnswers[i],num=state.examAnswers.filter(x=>x!==null).length;return `${header('KENNISTOETS',`Vraag ${i+1} van ${exam.length}`,'Kies één antwoord. Je krijgt na afloop uitleg bij alle vragen.',`<span class="pill outline">${num} / 16 beantwoord</span>`)}<div class="exam-container"><div class="progress" role="progressbar" aria-label="Vragen beantwoord" aria-valuenow="${num}" aria-valuemin="0" aria-valuemax="16"><i style="width:${num/16*100}%"></i></div><nav class="exam-qnav" aria-label="Toetsvragen">${exam.map((_,n)=>`<button data-exam-nav="${n}" aria-label="Vraag ${n+1}${state.examAnswers[n]!==null?', beantwoord':''}" class="${state.examAnswers[n]!==null?'filled':''} ${i===n?'current':''}" ${i===n?'aria-current="step"':''}>${n+1}</button>`).join('')}</nav><section class="quiz-box"><div class="eyebrow">${modules[q.module].short}</div><h3>${q.text}</h3><div class="answers">${q.options.map((o,n)=>`<button class="answer ${a===n?'selected':''}" data-exam-answer="${n}" aria-pressed="${a===n}"><span class="letter">${'ABCD'[n]}</span><span>${o}</span></button>`).join('')}</div><div class="question-actions"><button class="btn secondary" data-exam-nav="${i-1}" ${i===0?'disabled':''}>${icon('arrowLeft')} Vorige</button>${i<exam.length-1?`<button class="btn" data-exam-nav="${i+1}">Volgende vraag ${icon('arrow')}</button>`:`<button class="btn" data-action="submit-exam" ${num!==exam.length?'disabled':''}>Afronden en resultaat ${icon('check')}</button>`}</div>${i===exam.length-1&&num!==exam.length?'<div class="notice">Beantwoord eerst alle vragen. Via de vraagnummers kun je naar een open vraag gaan.</div>':''}</section>${num===exam.length&&i!==exam.length-1?'<button class="btn secondary" style="margin-top:18px" data-action="submit-exam">Alle vragen ingevuld · toets afronden</button>':''}</div>`;}
function examResult(answers){const score=answers.filter((x,i)=>x===exam[i].correct).length,critical=exam.map((q,i)=>({q,i})).filter(x=>x.q.critical),critGood=critical.filter(x=>answers[x.i]===x.q.correct).length,pass=score>=13&&critGood===critical.length;const repeat=[...new Set(exam.map((q,i)=>answers[i]!==q.correct?q.module:null).filter(x=>x!==null))];return `${header('JOUW TOETSRESULTAAT',pass?'De basis zit goed.':'Nog even oefenen.','Gebruik de feedback om je volgende leerstap te kiezen.')}<div class="result-summary"><div class="result-score">${Math.round(score/16*100)}<span style="font-size:1.7rem">%</span></div><div><h2>${score} van 16 antwoorden goed</h2><p>${critGood} van ${critical.length} kritieke veiligheidsvragen goed. ${pass?'Je voldoet aan de oefennorm.':'De oefennorm is minimaal 13 goed én alle 4 kritieke vragen goed.'}</p></div></div><div class="notice ${pass?'':'warning'}">${icon(pass?'shield':'warning')}<p>${pass?'Deze kennistoets toont begrip van de basis. Voor zelfstandig werk zijn ook de bedrijfsspecifieke instructie, een praktijkbeoordeling en de juiste bevoegdheid nodig.':'Herhaal de onderwerpen hieronder en maak de toets opnieuw. Je kunt de uitleg bij elke vraag openen.'}</p></div>${repeat.length?`<div class="paper"><h3>Jouw gerichte herhaling</h3><div class="flex" style="margin-top:15px">${repeat.map(i=>`<button class="btn secondary small" data-go="module" data-index="${i}">Module ${i+1} · ${modules[i].short} ${icon('arrow')}</button>`).join('')}</div></div>`:''}<div class="section-head" style="margin-top:30px"><h2>Alle antwoorden en uitleg</h2><button class="btn secondary small" data-action="start-exam">Opnieuw toetsen ${icon('refresh')}</button></div>${exam.map((q,i)=>`<details class="review-row ${answers[i]===q.correct?'':'incorrect'}"><summary>${icon(answers[i]===q.correct?'check':'warning')}<span>${i+1}. ${q.text} ${q.critical?'<span class="pill red">Kritiek</span>':''}</span></summary><div class="review-content"><p class="${answers[i]!==q.correct?'answer-given':''}">Jouw antwoord: ${q.options[answers[i]]||'Geen antwoord'}</p><p><strong>Juiste antwoord:</strong> ${q.options[q.correct]}</p><p>${q.why}</p><button class="btn ghost small" data-go="module" data-index="${q.module}">Bekijk module ${q.module+1} ${icon('arrow')}</button></div></details>`).join('')}<div class="flex" style="margin-top:24px">${pass?`<button class="btn primary" data-action="continue-course">${nextStage()===4?'Verder naar de werkplekkaart':'Verder met de leerroute'} ${icon('arrow')}</button>`:`<button class="btn primary" data-go="module" data-index="${repeat[0]??0}">Herhaal eerst module ${(repeat[0]??0)+1} ${icon('arrow')}</button>`}<button class="btn secondary" data-action="start-exam">Toets opnieuw maken</button></div>`;}
function fieldView(){return `${header('LEERSTAP 5 VAN 5 · NAAR DE WERKPLEK','De LOTOTO-werkplekkaart','Gebruik deze geheugensteun om de procedure op jouw locatie te bespreken.',`<button class="btn secondary" data-action="print">${icon('printer')} Afdrukken</button>`)}<div class="notice warning">${icon('warning')}<p><strong>Geheugensteun, geen schakel- of isolatieplan.</strong> Gebruik voor de uitvoering altijd de actuele installatiegebonden procedure, de vereiste vergunningen en de aangewezen bevoegde personen.</p></div><div class="field-grid">${steps.map((s,i)=>`<section class="field-step"><span class="field-no">${String(i+1).padStart(2,'0')}</span><div><h3>${s[0]}</h3><p>${s[1]}</p></div></section>`).join('')}</div><div class="paper" style="margin-top:24px"><h2>Bespreek dit op jouw werkplek</h2><ul class="checklist">${['Wie mag hier veiligstellen, verifiëren en vrijgeven?','Waar vind je het actuele isolatieplan voor deze installatie?','Hoe herken je alle bronnen, bypasses, terugvoedingen en restenergie?','Hoe borg je jouw persoonlijke bescherming bij groepswerk en ploegwissel?','Wie schakel je in bij een afwijking of een achtergebleven slot?','Welke controles blijven nodig tijdens de werkzaamheden?'].map(s=>`<li>${icon('check')}<span>${s}</span></li>`).join('')}</ul></div><div class="takeaway">${icon('warning')}<div><strong>Niet duidelijk? Niet veilig? Stop.</strong><br>Stel jezelf veilig, meld de afwijking en laat het plan controleren vóór je verdergaat.</div></div><div class="finish-panel no-print"><div><h3>Gelezen? Rond deze leerstap af.</h3><p>Neem de kaart mee naar je begeleider. Het praktijkgesprek en een bevoegdverklaring staan los van deze leeromgeving.</p></div><button class="btn primary" data-action="finish-course">Werkplekkaart gelezen ${icon('check')}</button></div><p class="print-only print-note">LOTOTO Praktijkacademie · Algemene leeromgeving · Inhoud gecontroleerd 24 september 2026. Geen vervanging van bedrijfsspecifieke instructie of bevoegdheid.</p>`;}
function sourcesView(){const terms=[['LOTOTO','Lock Out, Tag Out, Try Out: scheiden en vergrendelen, markeren en de werking van de veiligstelling controleren.'],['Energie-isolatie','Het fysiek scheiden van de werkplek van relevante energiebronnen volgens het isolatieplan.'],['Restenergie','Energie die na het scheiden nog aanwezig is, bijvoorbeeld druk, warmte, veerspanning of elektrische lading.'],['Terugvoeding','Energie die via een andere route de werkplek bereikt, bijvoorbeeld een extra voeding of een gekoppelde leiding.'],['Positieve scheiding','Een fysieke onderbreking die volgens de procedure nodig kan zijn, bijvoorbeeld een geschikte blindflens of het verwijderen van een leidingdeel.'],['Try Out','Verificatie dat de veiligstelling werkt. De controlemethode verschilt per energiebron. Een startpoging alleen bewijst geen elektrische spanningsloosheid.'],['Groepsslotkast','Een voorziening binnen een groepsprocedure om isolatiesleutels te borgen en meerdere medewerkers persoonlijk te beschermen.'],['Werkvergunning','Een afspraak over toestemming, werkzaamheden, risico’s en voorwaarden. De vergunning vervangt de fysieke veiligstelling niet.'],['TRA','Taakrisicoanalyse: vooraf de gevaren van de taak beoordelen en maatregelen vastleggen.'],['LMRA','Laatste Minuut Risico Analyse: vlak voor de start controleren of het werk op deze plek en dit moment veilig kan worden uitgevoerd.']];return `${header('NASLAG','Begrippen & bronnen','De betekenis achter de afkortingen en de uitgangspunten van deze leeromgeving.')}<div class="content-layout"><div class="paper"><h2>Begrippen in gewone taal</h2><dl class="glossary">${terms.map(t=>`<dt>${t[0]}</dt><dd>${t[1]}</dd>`).join('')}</dl></div><aside><div class="aside-card"><div class="eyebrow">OVER DEZE TRAINING</div><h3>Een algemene basis</h3><p>Voor nieuwe operators en monteurs in de procesindustrie. De precieze rollen, middelen, verificatie en werkvolgorde worden op jouw locatie vastgesteld.</p><p>De scenario’s en het pompschema zijn fictief. Een oefenresultaat geeft geen werkbevoegdheid.</p><span class="pill outline">Inhoud gecontroleerd · 24-09-2026</span></div></aside></div><section class="paper" style="margin-top:24px"><h2>Bronnen en afbakening</h2><p style="color:#62715e;margin-top:16px">De veiligheidsprincipes zijn gecontroleerd aan onderstaande officiële bronnen. OSHA en HSE zijn buitenlandse toezichthouders; hun publicaties zijn hier gebruikt als inhoudelijke referentie, niet als vervanging van Nederlandse regelgeving. Pas de training vóór bedrijfsmatige inzet aan op de RI&E, procedures, bevoegdheden en installaties van de werkgever.</p><div class="source-list"><div><a href="https://www.osha.gov/laws-regs/regulations/standardnumber/1910/1910.147" target="_blank" rel="noopener noreferrer">OSHA · Control of hazardous energy (1910.147) ↗</a><p>Referentie voor gevaarlijke energie, verificatie, groepswerk en continuïteit bij personeelswissels.</p></div><div><a href="https://www.osha.gov/laws-regs/regulations/standardnumber/1910/1910.147AppA" target="_blank" rel="noopener noreferrer">OSHA · Typical minimal lockout procedures ↗</a><p>Voorbeeld van de hoofdfasen, het beheersen van restenergie en het terug in bedrijf nemen.</p></div><div><a href="https://www.hse.gov.uk/work-equipment-machinery/maintenance.htm" target="_blank" rel="noopener noreferrer">HSE · Maintenance of work equipment ↗</a><p>Veilig onderhoud, isolatie, vergrendeling en ondersteuning van delen die kunnen vallen.</p></div><div><a href="https://www.arboportaal.nl/onderwerpen/veiligheid-op-het-werk/arbeidsmiddelen" target="_blank" rel="noopener noreferrer">Arboportaal · Arbeidsmiddelen ↗</a><p>Nederlandse overheidsinformatie over gebruik, onderhoud en keuring van arbeidsmiddelen.</p></div></div></section>`;}
document.addEventListener('click',event=>{const el=event.target.closest('button,[data-go],[data-point],[data-action]');if(!el||el.disabled)return;
if(el.dataset.scroll){document.getElementById(el.dataset.scroll)?.scrollIntoView({behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});return;}
if(el.dataset.stage!==undefined){openStage(Number(el.dataset.stage));return;}
if(el.dataset.lessonPart!==undefined){const p=Number(el.dataset.lessonPart);if(p<0||p>4)return;saved.reading=saved.reading&&typeof saved.reading==='object'?saved.reading:{};saved.reading[state.index]=p;persist();render();document.getElementById('lesson-content-title')?.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});return;}
if(el.dataset.go){event.preventDefault();go(el.dataset.go,Number(el.dataset.index)||0);return;}
if(el.dataset.point!==undefined){const n=Number(el.dataset.point);state.labSelection=n;state.tab='plant';if(!saved.visited.includes(n))saved.visited.push(n);persist();if(state.page!=='lab')go('lab');else render();document.getElementById('source-explanation')?.focus({preventScroll:true});document.getElementById('source-explanation')?.scrollIntoView({block:'nearest'});announce(labSources[n].title+': '+labSources[n].text);return;}
if(el.dataset.energy!==undefined){state.energy=Number(el.dataset.energy);render();document.querySelector(`[data-energy="${state.energy}"]`)?.focus({preventScroll:true});return;}
if(el.dataset.tab){state.tab=el.dataset.tab;render();return;}
if(el.dataset.lessonAnswer!==undefined){const n=Number(el.dataset.lessonAnswer);state.lessonAnswers[state.index]=n;render();announce(n===modules[state.index].q.correct?'Goed gekozen. Je kunt de module afronden.':'Nog niet veilig. Lees de feedback en probeer opnieuw.');document.querySelector(n===modules[state.index].q.correct?'[data-action="complete-module"]':`[data-lesson-answer="${n}"]`)?.focus({preventScroll:true});return;}
if(el.dataset.case!==undefined){state.caseStep=0;state.caseAnswers=[];state.caseChosen=null;state.caseDone=false;go('scenario',Number(el.dataset.case));return;}
if(el.dataset.caseAnswer!==undefined){state.caseChosen=Number(el.dataset.caseAnswer);state.caseAnswers[state.caseStep]=state.caseChosen;render();announce(cases[state.index].questions[state.caseStep].why);document.querySelector('[data-action="next-case"]')?.focus({preventScroll:true});return;}
if(el.dataset.move!==undefined){const i=Number(el.dataset.move),j=i+Number(el.dataset.direction);if(j<0||j>7)return;[state.order[i],state.order[j]]=[state.order[j],state.order[i]];state.orderChecked=false;render();document.querySelector(`[data-move="${j}"][data-direction="${el.dataset.direction}"]`)?.focus({preventScroll:true});announce(`${steps[state.order[j]][0]} staat op positie ${j+1}.`);return;}
if(el.dataset.examNav!==undefined){const n=Number(el.dataset.examNav);if(n>=0&&n<exam.length){state.examIndex=n;render();document.querySelector('.quiz-box h3')?.scrollIntoView({block:'nearest'});}return;}
if(el.dataset.examAnswer!==undefined){const n=Number(el.dataset.examAnswer);state.examAnswers[state.examIndex]=n;render();document.querySelector(`[data-exam-answer="${n}"]`)?.focus({preventScroll:true});announce(`Antwoord ${'ABCD'[n]} geselecteerd.`);return;}
switch(el.dataset.action){
case'continue-course':{const i=nextStage();openStage(i<0?4:i);break;}
case'finish-course':saved.fieldRead=true;persist();go('home');announce('Werkplekkaart gelezen. Bekijk je leervoortgang.');break;
case'menu':state.menu=!state.menu;render();break;
case'complete-module':if(state.lessonAnswers[state.index]!==modules[state.index].q.correct&&!saved.done.includes(state.index))return;if(!saved.done.includes(state.index))saved.done.push(state.index);persist();{const next=nextModule();if(next>=0)go('module',next);else openStage(nextStage()<0?4:nextStage());}announce('Module afgerond.');break;
case'next-case':if(state.caseChosen===null)return;if(state.caseStep===3){state.caseDone=true;saved.cases[state.index]={correct:state.caseAnswers.filter((a,i)=>a===cases[state.index].questions[i].c).length};persist();}else{state.caseStep++;state.caseChosen=null;}render();window.scrollTo({top:0,behavior:'instant'});break;
case'after-order':if(saved.visited.length<4){state.tab='plant';render();}else go('cases');break;
case'check-order':state.orderChecked=true;if(state.order.every((x,i)=>x===i)){saved.order=true;persist();}render();announce(state.order.every((x,i)=>x===i)?'De volgorde klopt.':'De volgorde klopt nog niet. Lees de feedback.');break;
case'shuffle-order':state.order=[5,2,0,6,1,4,7,3];state.orderChecked=false;render();break;
case'start-exam':state.examStarted=true;state.examSubmitted=false;state.examIndex=0;state.examAnswers=Array(exam.length).fill(null);render();window.scrollTo({top:0,behavior:'instant'});break;
case'submit-exam':if(state.examAnswers.some(x=>x===null))return;state.examSubmitted=true;saved.last={answers:[...state.examAnswers],date:new Date().toISOString()};persist();render();window.scrollTo({top:0,behavior:'instant'});break;
case'last-result':if(saved.last){state.examAnswers=[...saved.last.answers];state.examSubmitted=true;render();}break;
case'print':window.print();break;
case'reset':document.getElementById('reset-dialog').showModal();break;
case'cancel-reset':document.getElementById('reset-dialog').close();break;
case'confirm-reset':saved=fresh();persist();state.lessonAnswers={};state.caseAnswers=[];state.caseStep=0;state.caseChosen=null;state.caseDone=false;state.order=[3,0,5,1,4,2,7,6];state.orderChecked=false;state.examStarted=false;state.examSubmitted=false;state.examAnswers=Array(exam.length).fill(null);go('home');announce('Je voortgang is gewist.');break;
}});
document.addEventListener('change',e=>{if(e.target.id==='role'){saved.role=e.target.value;persist();render();document.getElementById('role')?.focus();announce(`Rol gewijzigd naar ${saved.role==='operator'?'operator':'monteur technische dienst'}.`);}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-point]')&&e.target.tagName.toLowerCase()!=='button'){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}if(e.key==='Escape'&&state.menu){state.menu=false;render();}});
window.addEventListener('popstate',()=>{route();if(state.page==='scenario'){state.caseStep=0;state.caseAnswers=[];state.caseChosen=null;state.caseDone=false;}render();});
route();render();
// Structured access to the same local learning state when supported by the browser.
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 const toolDefs=[
 {name:'read_learning_progress',title:'Lees LOTOTO-leervoortgang',description:'Lees de apparaatgebonden leervoortgang en de huidige pagina. Verandert geen antwoorden of resultaten.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(input===null||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw new Error('Verwacht een leeg object.');return {role:saved.role,page:state.page,completedModules:saved.done.map(i=>i+1),completedScenarios:Object.keys(saved.cases).length,modulesTotal:8,lastScore:saved.last?saved.last.answers.filter((a,i)=>a===exam[i].correct).length:null};}},
 {name:'open_learning_module',title:'Open een LOTOTO-leermodule',description:'Open een van de acht leermodules. Markeert de module niet als afgerond en beantwoordt geen oefenvraag.',inputSchema:{type:'object',properties:{module:{type:'integer',minimum:1,maximum:8}},required:['module'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).some(k=>k!=='module')||!Number.isInteger(input.module)||input.module<1||input.module>8)throw new Error('Kies een modulenummer van 1 tot en met 8.');go('module',input.module-1);return {page:'module',module:input.module,title:modules[input.module-1].title};}}
 ];
 for(const tool of toolDefs){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
